const item = $input.first().json;
const src = (item.body && typeof item.body === 'object') ? item.body : item;
const message = String(src.message || '').trim();
const customerId = String(src.customer_id || '').trim();
const errors = [];
if (!message) errors.push('message is required');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(customerId)) errors.push('customer_id must be the customer UUID from the customers table');
const toText = v => (v === undefined || v === null) ? '' : (typeof v === 'string' ? v : JSON.stringify(v));
return [{ json: {
  valid: errors.length === 0, errors,
  customer_id: customerId, message,
  intent: toText(src.intent), memory: toText(src.memory), context: toText(src.context),
  supabase_url: String(item.supabase_url || '').replace(/\/+$/, ''),
  embed_model: item.embed_model, llm_model: item.llm_model
} }];

const ctx = $('Normalize Input').first().json;
const items = $input.all().map(i => i.json).filter(p => p && p.sku);
const products = items.map(p => ({
  sku: p.sku, name: p.name, description: p.description, category: p.category,
  price: p.price, currency: p.currency, in_stock: p.in_stock, stock_quantity: p.stock_quantity,
  specs: p.specs || {}, similarity: Number(p.similarity)
}));
const na = v => (v === null || v === undefined || v === '') ? 'NOT AVAILABLE' : v;
const productContext = products.map(p => [
  'SKU: ' + p.sku, 'Name: ' + p.name, 'Category: ' + na(p.category), 'Description: ' + na(p.description),
  'Price: ' + (p.price === null ? 'NOT AVAILABLE' : p.price + ' ' + na(p.currency)),
  'In stock: ' + (p.in_stock === null ? 'NOT AVAILABLE' : p.in_stock),
  'Stock quantity: ' + na(p.stock_quantity),
  'Specs: ' + (Object.keys(p.specs).length ? JSON.stringify(p.specs) : 'NOT AVAILABLE')
].join('\n')).join('\n---\n');
const system = 'You are the Sales Agent of a small business. Answer ONLY from the PRODUCT DATA provided. Rules: (1) Never invent products, prices, availability, discounts, specifications or quote values. (2) If the data does not contain what the customer asks, say clearly that you do not have enough verified information about it. (3) Never offer or mention discounts; there is no discount data. (4) You may recommend products and suggest an upsell only among the listed products, using only facts present in the data. (5) CUSTOMER MEMORY is background only, never a source of product facts. (6) Reply in the same language as the customer message. (7) If the customer asks for a quote, put the SKU and quantity in quote_request; do NOT calculate totals yourself, the system calculates them. If the quantity is not stated, ask the customer and set requested to false. Return ONLY a JSON object: {"response": string, "confidence": number between 0 and 1, "used_skus": [string], "quote_request": {"requested": boolean, "items": [{"sku": string, "quantity": integer}]}}. confidence reflects how well the product data supports your answer.';
const user = 'PRODUCT DATA:\n' + (productContext || 'NONE') + '\n\nCUSTOMER MEMORY (background only):\n' + (ctx.memory || 'none') + '\n\nCUSTOMER MESSAGE:\n' + ctx.message + (ctx.context ? '\n\nSUPERVISOR REVIEW NOTE (a previous answer was rejected; answer again using ONLY the product data above and remove any claim not supported by it):\n' + ctx.context : '');
return [{ json: { customer_id: ctx.customer_id, message: ctx.message, supabase_url: ctx.supabase_url, llm_model: ctx.llm_model,
  has_products: products.length > 0, products, evidence: products.map(p => ({ sku: p.sku, name: p.name, category: p.category, price: p.price, currency: p.currency, in_stock: p.in_stock, stock_quantity: p.stock_quantity, specs: p.specs })), system_prompt: system, user_prompt: user } }];

return [{ json: { success: true,
  response: "I'm sorry, I don't have enough verified product information to answer this right now. / দুঃখিত, এই বিষয়ে আমার কাছে যাচাইকৃত পর্যাপ্ত তথ্য নেই।",
  confidence: 0.2, data: { reason: 'no_products_found', evidence: [] }, needs_human: false, error: null, agent: 'sales' } }];

const ctx = $('Build Context').first().json;
const ai = $input.first().json;
let content = ai.choices[0].message.content;
content = String(content).replace(/```json|```/g, '').trim();
const p = JSON.parse(content);
let response = String(p.response || '').trim();
if (!response) throw new Error('LLM returned an empty response');
let confidence = Math.max(0, Math.min(1, Number(p.confidence) || 0));
const bySku = {};
ctx.products.forEach(x => { bySku[x.sku] = x; });
const usedSkus = (Array.isArray(p.used_skus) ? p.used_skus : []).filter(s => bySku[s]);
const qr = p.quote_request || {};
let createQuote = false, quotePayload = null, issues = [];
if (qr.requested === true && Array.isArray(qr.items) && qr.items.length) {
  const lines = [];
  let currency = null;
  for (const it of qr.items) {
    const prod = bySku[it.sku];
    const qty = Number(it.quantity);
    if (!prod) { issues.push('unknown SKU ' + it.sku); continue; }
    if (!Number.isInteger(qty) || qty < 1 || qty > 1000) { issues.push('invalid quantity for ' + it.sku); continue; }
    if (prod.price === null || prod.price === undefined || !prod.currency) { issues.push('price not available for ' + it.sku); continue; }
    if (prod.in_stock !== true) { issues.push('availability not verified for ' + it.sku); continue; }
    if (currency && currency !== prod.currency) { issues.push('mixed currencies'); continue; }
    currency = prod.currency;
    lines.push({ sku: prod.sku, name: prod.name, quantity: qty, unit_price: Number(prod.price), line_total: Math.round(Number(prod.price) * qty * 100) / 100, currency });
  }
  if (lines.length && issues.length === 0) {
    const total = Math.round(lines.reduce((s, l) => s + l.line_total, 0) * 100) / 100;
    createQuote = true;
    quotePayload = { customer_id: ctx.customer_id, items: lines, total, currency, status: 'draft' };
    response += '\n\nQuote (draft):\n' + lines.map(l => l.sku + ' x ' + l.quantity + ' @ ' + l.unit_price + ' = ' + l.line_total + ' ' + l.currency).join('\n') + '\nTotal: ' + total + ' ' + currency;
  } else if (issues.length) {
    response += '\n\nNote: a quote could not be created because verified data was missing or invalid: ' + issues.join('; ') + '.';
    confidence = Math.min(confidence, 0.5);
  }
}
return [{ json: { create_quote: createQuote, quote_payload: quotePayload, response, confidence, used_skus: usedSkus, quote_issues: issues, supabase_url: ctx.supabase_url } }];

const p = $('Parse & Prepare Quote').first().json;
let quote = null;
try { const q = $('Insert Quote').first().json; if (q && q.id) quote = q; } catch (e) {}
return [{ json: { success: true, response: p.response, confidence: p.confidence,
  data: { used_skus: p.used_skus, quote_id: quote ? quote.id : null, quote_total: quote ? quote.total : null, quote_issues: p.quote_issues, evidence: $('Build Context').first().json.evidence },
  needs_human: false, error: null, agent: 'sales' } }];

const j = $input.first().json || {};
const e = j.error || j;
const msg = String(e.message || e.description || (typeof e === 'string' ? e : JSON.stringify(e))).slice(0, 500);
return [{ json: { success: false, response: null, confidence: 0, data: {}, needs_human: true, error: 'sales_agent_failed: ' + msg, agent: 'sales' } }];
